import zipfile, xml.etree.ElementTree as ET, statistics, re
ns={'a':'http://schemas.openxmlformats.org/drawingml/2006/main','p':'http://schemas.openxmlformats.org/presentationml/2006/main','r':'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}
RID='{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id'

def local(tag):
    return tag.split('}')[-1]

def geom_any(el):
    offs=[]; exts=[]
    for d in el.iter():
        lt=local(d.tag)
        if lt=='off' and 'x' in d.attrib and 'y' in d.attrib:
            if str(d.attrib['x']).isdigit() and str(d.attrib['y']).isdigit():
                offs.append((int(d.attrib['x']), int(d.attrib['y'])))
        elif lt=='ext' and 'cx' in d.attrib and 'cy' in d.attrib:
            if str(d.attrib['cx']).isdigit() and str(d.attrib['cy']).isdigit():
                exts.append((int(d.attrib['cx']), int(d.attrib['cy'])))
    if offs and exts:
        x,y=offs[0]; cx,cy=exts[0]
        return x,y,cx,cy
    return 0,0,0,0

def parse_ppt(path, max_slides=50):
    z=zipfile.ZipFile(path)
    pres=ET.fromstring(z.read('ppt/presentation.xml'))
    sldSz=pres.find('p:sldSz', ns)
    W,H=int(sldSz.attrib['cx']), int(sldSz.attrib['cy'])
    pres_rels=ET.fromstring(z.read('ppt/_rels/presentation.xml.rels'))
    relmap={rel.attrib['Id']:rel.attrib['Target'] for rel in pres_rels}
    slide_paths=[]
    for sldId in pres.findall('p:sldIdLst/p:sldId', ns):
        slide_paths.append('ppt/'+relmap[sldId.attrib[RID]].lstrip('/'))
    slides=[]
    for spath in slide_paths[:max_slides]:
        root=ET.fromstring(z.read(spath))
        spTree=root.find('p:cSld/p:spTree', ns)
        texts=[]; pic_count=0; gfx_count=0; pic_area=0; text_area=0
        for child in list(spTree):
            tag=local(child.tag)
            x,y,cx,cy=geom_any(child)
            area=cx*cy
            if tag=='pic':
                pic_count+=1; pic_area+=area
            elif tag=='graphicFrame':
                gfx_count+=1; pic_area+=area
            elif tag=='sp':
                t=''.join([(n.text or '') for n in child.findall('.//a:t', ns)]).strip()
                if t:
                    texts.append(t)
                    text_area+=area
            elif tag=='grpSp':
                # count children in grouped shapes too
                for d in child:
                    dtag=local(d.tag)
                    dx,dy,dcx,dcy=geom_any(d)
                    darea=dcx*dcy
                    if dtag=='pic':
                        pic_count+=1; pic_area+=darea
                    elif dtag=='graphicFrame':
                        gfx_count+=1; pic_area+=darea
                    elif dtag=='sp':
                        t=''.join([(n.text or '') for n in d.findall('.//a:t', ns)]).strip()
                        if t:
                            texts.append(t)
                            text_area+=darea
        slides.append({'texts':texts,'pic_count':pic_count,'gfx_count':gfx_count,'pic_ratio':pic_area/(W*H),'text_ratio':text_area/(W*H)})
    return W,H,slides

